from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.t1 = OrderedDict()
        self.t2 = OrderedDict()
        self.b1 = OrderedDict()
        self.b2 = OrderedDict()
        self.t1_bytes = 0
        self.t2_bytes = 0
        self.target_t1 = self.capacity_bytes // 2
        self.ghost_limit = 4096

    def _remember(self, ghost, key):
        ghost.pop(key, None)
        ghost[key] = None
        while len(ghost) > self.ghost_limit:
            ghost.popitem(last=False)

    def _replace(self, prefer_t1):
        if prefer_t1 and self.t1:
            key, size = self.t1.popitem(last=False)
            self.t1_bytes -= size
            self._remember(self.b1, key)
            return key
        if self.t2:
            key, size = self.t2.popitem(last=False)
            self.t2_bytes -= size
            self._remember(self.b2, key)
            return key
        if self.t1:
            key, size = self.t1.popitem(last=False)
            self.t1_bytes -= size
            self._remember(self.b1, key)
            return key
        return None

    def _remove_ghost(self, key):
        self.b1.pop(key, None)
        self.b2.pop(key, None)

    def _adapt(self, upward):
        if self.capacity_bytes <= 0:
            return
        step = max(1, self.capacity_bytes // 16)
        if upward:
            self.target_t1 = min(self.capacity_bytes, self.target_t1 + step)
        else:
            self.target_t1 = max(0, self.target_t1 - step)

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self.t1:
            stored = self.t1.pop(key)
            self.t1_bytes -= stored
            self.t2[key] = stored
            self.t2_bytes += stored
            return []

        if key in self.t2:
            stored = self.t2.pop(key)
            self.t2[key] = stored
            return []

        if size <= 0 or size > self.capacity_bytes or self.capacity_bytes == 0:
            return []

        in_b1 = key in self.b1
        in_b2 = key in self.b2
        if in_b1:
            self._adapt(True)
        elif in_b2:
            self._adapt(False)
        self._remove_ghost(key)

        evicted = []
        while self.t1_bytes + self.t2_bytes + size > self.capacity_bytes:
            prefer_t1 = self.t1_bytes > self.target_t1
            old_key = self._replace(prefer_t1)
            if old_key is None:
                break
            evicted.append(old_key)

        self.t2[key] = size if in_b2 else size
        self.t2_bytes += size
        while len(self.b1) + len(self.b2) > self.ghost_limit:
            if len(self.b1) >= len(self.b2) and self.b1:
                self.b1.popitem(last=False)
            elif self.b2:
                self.b2.popitem(last=False)
            else:
                break
        return evicted
